package app.dayflow;
import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.widget.*;import com.google.android.material.materialswitch.MaterialSwitch;import org.json.*;import java.security.*;
/** Opt-in local API. A separate optional APK provides the HTTP bridge. */
final class AssistantApi {static final String PACKAGE="app.dayflow.assistant";static boolean enabled(Context c){return c.getSharedPreferences("settings",0).getBoolean("assistant_api",false);}static void stop(Context c){c.sendBroadcast(new Intent("app.dayflow.assistant.STOP").setPackage(PACKAGE),"app.dayflow.permission.INTERNAL");}static String rotate(Context c)throws Exception{byte[] key=new byte[32];new SecureRandom().nextBytes(key);String value=android.util.Base64.encodeToString(key,android.util.Base64.NO_WRAP|android.util.Base64.URL_SAFE);Secrets.put(c,"assistant_api",value);stop(c);return value;}
 static void show(MainActivity a){LinearLayout page=a.fullPage("开放API与语音助手",a::home);page.addView(Ui.help(a,"默认关闭，仅本机使用。内容接口由访问密钥授权，不暴露云端密码或AI Key。蓝心小V/小爱同学需要相应的自定义工具或自动化桥接，不能假定开启后自动获得厂商权限。"));MaterialSwitch enabled=new MaterialSwitch(a);enabled.setText("允许本机助手API访问");enabled.setChecked(enabled(a));enabled.setOnCheckedChangeListener((view,on)->{try{if(on&&Secrets.get(a,"assistant_api").isEmpty())rotate(a);a.prefs.edit().putBoolean("assistant_api",on).commit();if(!on)stop(a);}catch(Exception e){a.message(e.getMessage());enabled.setChecked(false);}});page.addView(enabled);page.addView(Ui.text(a,"HTTP：127.0.0.1:8766（需可选助手插件）\n原生：content://app.dayflow.api",14,false));page.addView(Ui.button(a,"复制本机API密钥",false,()->{try{if(!enabled(a))throw new Exception("请先开启API");String key=Secrets.get(a,"assistant_api");((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("日栖本机API密钥",key));a.message("密钥已复制，仅交给信任的本机工具");}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"重置密钥并断开现有桥接",false,()->{try{rotate(a);a.message("旧密钥已失效");}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"开启本机HTTP桥接",true,()->{try{if(!enabled(a))throw new Exception("请先开启API");if(!DocumentPlugins.ready(a,PACKAGE))return;a.startActivityForResult(new Intent("app.dayflow.action.ASSISTANT_API").setPackage(PACKAGE).putExtra("dayflow_protocol",1).putExtra("dayflow_api_token",Secrets.get(a,"assistant_api")),116);}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"停止HTTP桥接",false,()->{stop(a);a.message("已通知插件停止；关闭API可立即撤销所有访问");}));page.addView(Ui.button(a,"下载可选助手API插件",false,()->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/cniv14/DayFlow/releases/latest/download/DayFlow-assistant.apk")))));}
 static JSONObject execute(Context c,String method,JSONObject input)throws Exception{Data db=Data.get(c);if(method.equals("capabilities"))return new JSONObject().put("protocol",1).put("methods",new JSONArray(java.util.Arrays.asList("capabilities","today","search_notes","capture","create_note","create_task","complete_task"))).put("scope","local");if(method.equals("today")||method.equals("search_notes")){JSONArray all=method.equals("today")?db.dayTasks(java.time.LocalDate.parse(input.optString("date",java.time.LocalDate.now().toString()))):db.notes(input.optString("query"));JSONArray rows=new JSONArray();int offset=Math.max(0,input.optInt("offset")),limit=Math.max(1,Math.min(50,input.optInt("limit",20)));for(int i=offset;i<all.length()&&rows.length()<limit;i++)rows.put(summary(all.getJSONObject(i)));return new JSONObject().put("items",rows).put("next_offset",offset+rows.length()).put("has_more",offset+rows.length()<all.length());}if(method.equals("complete_task")){JSONObject r=db.find(input.getString("id"));if(r==null||r.optBoolean("deleted")||!java.util.Arrays.asList("task","event","course","project").contains(r.optString("kind")))throw new Exception("无效待办ID");if(r.optString("completed").isEmpty())TaskActions.complete(c,r);return summary(db.find(r.getString("id")));}String kind=method.equals("create_note")?"note":method.equals("create_task")?"task":method.equals("capture")?"inbox":"";if(kind.isEmpty())throw new Exception("未知API方法");String content=input.optString("content");if(input.has("content_uri")){android.net.Uri uri=android.net.Uri.parse(input.getString("content_uri"));if(!"content".equals(uri.getScheme())||!"app.dayflow.assistant.files".equals(uri.getAuthority()))throw new Exception("无效输入文件授权");try(java.io.InputStream in=c.getContentResolver().openInputStream(uri)){content=MarkdownFiles.read(in);}}JSONObject r=Data.make(kind,input.optString("title",kind.equals("note")?java.time.LocalDate.now().toString():"助手收集")).put("content",content).put("source","语音助手API");for(String field:new String[]{"start_at","end_at","due_date","location","time_hint"})if(input.has(field))r.put(field,input.optString(field));if(kind.equals("inbox"))r.put("confirmation_status","pending").put("proposed_kind","task");if(kind.equals("note"))r.put("content_format","markdown");if(input.has("request_id")){String key=input.getString("request_id");java.util.UUID.fromString(key);String id=java.util.UUID.nameUUIDFromBytes(("dayflow:assistant:"+key).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();JSONObject existing=db.find(id);if(existing!=null)return summary(existing);r.put("id",id);}Data.validate(r);db.save(r);return summary(r);}
 private static JSONObject summary(JSONObject r)throws Exception{JSONObject result=new JSONObject();for(String key:new String[]{"id","kind","title","start_at","end_at","due_date","location","completed","revision","confirmation_status"})if(r.has(key))result.put(key,r.get(key));String text=r.optString("content");return result.put("preview",text.substring(0,Math.min(512,text.length())));}
}
